const transactions = $input.all();
const lastMonth = new Date();
lastMonth.setMonth(lastMonth.getMonth() - 1);

const monthStart = new Date(lastMonth.getFullYear(), lastMonth.getMonth(), 1);
const monthEnd = new Date(lastMonth.getFullYear(), lastMonth.getMonth() + 1, 0);

// Filter transactions from last month
const filtered = transactions.filter(item => {
  const date = new Date(item.json.Date);
  return date >= monthStart && date <= monthEnd;
});

// Calculate statistics
const total = filtered.reduce((sum, item) => sum + (item.json.Amount || 0), 0);

// Explicitly type categories as a record with string keys and number values
const categories = {};
filtered.forEach(item => {
  const cat = item.json.Category || 'Uncategorized';
  categories[cat] = (categories[cat] || 0) + (item.json.Amount || 0);
});

const sortedCategories = Object.entries(categories)
  .sort(([,a], [,b]) => b - a)
  .slice(0, 5);

return [{
  json: {
    period: `${monthStart.toLocaleDateString('en-US', {month: 'long', year: 'numeric'})}`,
    total_transactions: filtered.length,
    total_amount: total.toFixed(2),
    average_transaction: (total / filtered.length).toFixed(2),
    top_categories: sortedCategories,
    all_transactions: filtered.map(t => t.json)
  }
}];

